def transform(grid):
    # Determine dimensions
    H = len(grid)
    W = len(grid[0])

    # Identify background color (most frequent)
    counts = {}
    for r in range(H):
        for c in range(W):
            val = grid[r][c]
            counts[val] = counts.get(val, 0) + 1
    bg = max(counts, key=counts.get)

    # Identify separator column (column of 2s)
    sep_c = -1
    for c in range(W):
        is_sep = True
        for r in range(H):
            if grid[r][c] != 2:
                is_sep = False
                break
        if is_sep:
            sep_c = c
            break

    if sep_c == -1:
        return grid  # No separator found, return as is

    # Identify object color
    # Find color that is neither background nor 2
    possible_colors = [x for x in counts if x != bg and x != 2]
    obj_c = None
    if possible_colors:
        # In case multiple colors, pick the one forming a shape or just the first valid
        # Based on problem types, usually just one color exists.
        obj_c = possible_colors[0]

    if obj_c is None:
        return grid

    # Identify object bounding box
    min_c = W
    max_c = -1
    has_obj = False
    for r in range(H):
        for c in range(W):
            if grid[r][c] == obj_c:
                has_obj = True
                if c < min_c: min_c = c
                if c > max_c: max_c = c

    if not has_obj:
        return grid

    # Calculate shift
    # If object is to the right of separator (min_c > sep_c)
    if min_c > sep_c:
        target_min = sep_c + 1
        shift = target_min - min_c
    else:
        # Object is to the left (max_c < sep_c)
        target_max = sep_c - 1
        shift = target_max - max_c

    # Prepare output grid
    output = [row[:] for row in grid]

    # Clear original object positions (fill with background)
    for r in range(H):
        for c in range(W):
            if grid[r][c] == obj_c:
                output[r][c] = bg

    # Move object to new positions
    for r in range(H):
        for c in range(W):
            if grid[r][c] == obj_c:
                nc = c + shift
                if 0 <= nc < W:
                    output[r][nc] = obj_c

    # Fill column corresponding to original max_c with 8s
    for r in range(H):
        if 0 <= max_c < W:
            output[r][max_c] = 8

    return output
